(() => {
  // Get all dt (definition term) entries - each represents an article
  const dts = document.querySelectorAll('dt');
  const results = [];
  let currentDay = '';
  const targetDay = 'Thu, 24 Sep 2026';
  dts.forEach((dt) => {
    // Walk up to find the parent dl
    const dl = dt.parentElement;
    const prev = dl.previousElementSibling;
    if (prev && prev.tagName === 'H3') {
      const dayMatch = prev.textContent.match(/(Sun|Mon|Tue|Wed|Thu|Fri|Sat), \d{1,2} [A-Za-z]+ \d{4}/);
      if (dayMatch) currentDay = dayMatch[0];
    }
    const dd = dt.nextElementSibling;
    if (dd && dd.tagName === 'DD') {
      const titleEl = dd.querySelector('.list-title');
      const text = (titleEl ? titleEl.innerText : dd.innerText);
      if (currentDay === targetDay) {
        results.push({day: currentDay, title: text.slice(0, 200)});
      }
    }
  });
  return {count: results.length, results: results.slice(0, 5), totalSample: results.length};
})();

(() => {
  const dts = document.querySelectorAll('dt');
  const targetDay = 'Thu, 24 Sep 2026';
  let currentDay = '';
  const entries = [];

  // Walk all dt and their sibling sections to find day headers
  const dl = document.querySelector('dl#articles');
  if (!dl) return {error: 'No dl found', count: dts.length};

  // Iterate through all elements in document order
  let dayEntries = [];
  let inTargetDay = false;

  // Find all H3 elements with day info
  const h3s = document.querySelectorAll('h3');
  const daySections = [];
  h3s.forEach((h3) => {
    const m = h3.textContent.match(/(Sun|Mon|Tue|Wed|Thu|Fri|Sat), (\d{1,2}) ([A-Za-z]+) (\d{4}) \(showing/);
    if (m) {
      daySections.push({day: `${m[1]}, ${m[2]} ${m[3]} ${m[4]}`, header: h3});
    }
  });

  if (!daySections.find(s => s.day === targetDay)) {
    return {error: 'Target day not found', availableDays: daySections.map(s => s.day)};
  }

  // Find the section between target day's H3 and next H3
  const targetIdx = daySections.findIndex(s => s.day === targetDay);
  const startH3 = daySections[targetIdx].header;
  const endH3 = targetIdx + 1 < daySections.length ? daySections[targetIdx + 1].header : null;

  // Collect all dts between these
  let el = startH3.nextElementSibling;
  const targetEntries = [];
  while (el && el !== endH3) {
    if (el.tagName === 'DT') {
      const dd = el.nextElementSibling;
      if (dd) {
        const entryInfo = {
          arxivId: '',
          title: '',
          subjects: '',
          comments: ''
        };
        // Get arxiv id from dt
        const idMatch = el.textContent.match(/arXiv:[\d.]+/);
        if (idMatch) entryInfo.arxivId = idMatch[0];
        // Get title from dd
        const titleEl = dd.querySelector('.list-title');
        if (titleEl) entryInfo.title = titleEl.innerText.trim();
        // Get subjects
        const subjMatch = dd.textContent.match(/Subjects:([^\n]+)/);
        if (subjMatch) entryInfo.subjects = subjMatch[1].trim();
        // Get comments
        const commMatch = dd.textContent.match(/Comments:([^S]+?)(?=Subjects:|$)/);
        if (commMatch) entryInfo.comments = commMatch[1].trim();
        targetEntries.push(entryInfo);
      }
    }
    el = el.nextElementSibling;
  }

  return {day: targetDay, count: targetEntries.length, entries: targetEntries};
})();

(() => {
  // Find the H3 with Thu, 24 Sep 2026
  const h3s = document.querySelectorAll('h3');
  const targetH3 = Array.from(h3s).find(h => h.textContent.includes('Thu, 24 Sep 2026'));
  if (!targetH3) return {error: 'H3 not found'};

  // Find next H3
  const allH3s = Array.from(h3s);
  const idx = allH3s.indexOf(targetH3);
  const nextH3 = allH3s[idx + 1];

  const entries = [];
  let el = targetH3.nextElementSibling;
  while (el && el !== nextH3) {
    if (el.tagName === 'DT') {
      const dd = el.nextElementSibling;
      if (dd && dd.tagName === 'DD') {
        const idMatch = el.textContent.match(/arXiv:[\d.]+/);
        const titleEl = dd.querySelector('.list-title');
        const text = dd.textContent;
        const subjMatch = text.match(/Subjects:([^\n]+)/);
        entries.push({
          id: idMatch ? idMatch[0] : '',
          title: titleEl ? titleEl.textContent.trim() : '',
          subjects: subjMatch ? subjMatch[1].trim() : ''
        });
      }
    }
    el = el.nextElementSibling;
  }

  // Filter for "autonomous vehicle" entries
  const autonomousEntries = entries.filter(e => 
    /autonomous\s+vehicle/i.test(e.title + ' ' + e.subjects)
  );

  return {totalEntries: entries.length, autonomousMatches: autonomousEntries.length, matches: autonomousEntries};
})();

