(() => {
  try {
    // Get all entries directly with their parent day
    const h3s = document.querySelectorAll('h3');
    const dayOrder = [];
    const dayToH3 = {};
    h3s.forEach((h3, i) => {
      const m = h3.textContent.match(/(Sun|Mon|Tue|Wed|Thu|Fri|Sat), (\d{1,2}) ([A-Za-z]+) (\d{4})/);
      if (m) {
        const day = `${m[1]}, ${m[2]} ${m[3]} ${m[4]}`;
        dayOrder.push(day);
        dayToH3[day] = h3;
      }
    });

    // Get the dl
    const dl = document.querySelector('dl#articles');
    if (!dl) return JSON.stringify({error: 'No dl', dayOrder});

    // Get all dt and pair with day
    const dts = dl.querySelectorAll('dt');
    const results = [];
    let currentDay = dayOrder[0];

    dts.forEach((dt) => {
      // Check if dt has a previousSibling H3
      let prev = dt.previousElementSibling;
      while (prev) {
        if (prev.tagName === 'H3') {
          const m = prev.textContent.match(/(Sun|Mon|Tue|Wed|Thu|Fri|Sat), (\d{1,2}) ([A-Za-z]+) (\d{4})/);
          if (m) {
            currentDay = `${m[1]}, ${m[2]} ${m[3]} ${m[4]}`;
          }
          break;
        }
        prev = prev.previousElementSibling;
      }

      const dd = dt.nextElementSibling;
      if (dd && dd.tagName === 'DD') {
        const idMatch = dt.textContent.match(/arXiv:[\d.]+/);
        const titleEl = dd.querySelector('.list-title');
        const text = dd.textContent;
        const subjMatch = text.match(/Subjects:([^S]+?)(?=Subjects:|$)/);
        results.push({
          day: currentDay,
          id: idMatch ? idMatch[0] : '',
          title: titleEl ? titleEl.textContent.trim() : '',
          subjectStr: subjMatch ? subjMatch[1].trim() : ''
        });
      }
    });

    // Filter Thu 24 entries
    const thu24Entries = results.filter(e => e.day === 'Thu, 24 Sep 2026');

    // Search for autonomous vehicles
    const avEntries = thu24Entries.filter(e => {
      const searchStr = (e.title + ' ' + e.subjectStr).toLowerCase();
      return /autonomous\s+vehicle/.test(searchStr);
    });

    return JSON.stringify({
      totalEntries: results.length,
      thu24Count: thu24Entries.length,
      avCount: avEntries.length,
      avEntries: avEntries.slice(0, 20),
      allDays: dayOrder
    });
  } catch (e) {
    return JSON.stringify({error: e.message, stack: e.stack});
  }
})();

